    <section class="resource-bar" aria-label="城门和资源"><div class="gate-resource">${D(`gate`)}<div><div class="resource-label">城门耐久 <strong id="hp-text"></strong></div><div class="health-track"><i id="hp-fill"></i></div></div></div><div class="coin-resource">${D(`coin`)}<strong id="gold"></strong><span>金币</span></div></section>
