    <footer class="controls"><button id="sell" class="secondary-button sell-button" disabled>${D(`sell`)}<span>遣散<span id="sell-price">选中守卫</span></span></button><button id="summon" class="primary-button">${D(`spark`)}<span>召唤守卫<small>18 金币 / 次</small></span><b>＋</b></button><button id="skill" class="secondary-button skill-button">${D(`bell`)}<span>破晓钟<small id="skill-time">范围伤害</small></span></button></footer>
